SN=E('Citizenship Education','የዜግነት ትምህርት')
def U(n,title,extra,exam,nt,summ,foot):
    unit(f'g8-citizen-{n}','citizen',SN,E(f'Unit {n}',f'ክፍል {n}'),E(*title),E(f'Built on the Grade 8 Citizenship Education student textbook, Unit {n}: {foot[0]}.',f'በ8ኛ ክፍል የዜግነት ትምህርት መጽሐፍ ክፍል {n} ላይ የተመሰረተ፦ {foot[1]}።'),'(d=>[])',{},extra,exam,nt,summ)

